class Completed {

    public int hIndex(int[] citations) {

        int n = citations.length;
        int[] counts = new int[n + 1];

        for (int citation : citations) {
            if (citation >= n) {
                counts[n]++;
            } else {
                counts[citation]++;
            }
        }

        int total = 0;

        for (int h = n; h >= 0; h--) {
            total += counts[h];
            if (total >= h) {
                return h;
            }
        }

        return 0;
    }
}

